import type { Bar, MarketCode, Quote } from '../core/index.ts';
import { ConnectorError, type MarketDataConnector } from './connector.ts';

export interface SourceAttempt { connector: string; ok: boolean; error?: string; ms: number }

/**
 * Ordered list of connectors per market: primary first, then fallbacks.
 * The first enabled connector that succeeds wins; every attempt is returned
 * so the job can write it to `ingestion_runs` and alert the admin.
 */
export class ConnectorRegistry {
  constructor(private byMarket: Partial<Record<MarketCode, MarketDataConnector[]>>) {}

  connectors(market: MarketCode) {
    return (this.byMarket[market] ?? []).filter((c) => c.isEnabled());
  }

  private async run<T>(market: MarketCode, fn: (c: MarketDataConnector) => Promise<T>, accept: (v: T) => boolean = () => true) {
    const attempts: SourceAttempt[] = [];
    for (const c of this.connectors(market)) {
      const t0 = Date.now();
      try {
        const v = await fn(c);
        if (!accept(v)) throw new ConnectorError(c.id, 'réponse vide');
        attempts.push({ connector: c.id, ok: true, ms: Date.now() - t0 });
        return { value: v, source: c.id, attempts };
      } catch (e) {
        attempts.push({ connector: c.id, ok: false, error: (e as Error).message, ms: Date.now() - t0 });
      }
    }
    return { value: null, source: null, attempts };
  }

  quotes(market: MarketCode) {
    return this.run<Quote[]>(market, (c) => c.getQuotes(market), (v) => v.length > 0);
  }

  history(market: MarketCode, ticker: string, from: string, to: string) {
    return this.run<Bar[]>(market, (c) => c.getHistory(market, ticker, from, to), (v) => v.length > 0);
  }
}
